import React, { useState } from 'react'
import listJustEmptyPage from './listRendering/just-empty-page.jsx'
import maping from './listRendering/mapping-an-array-to-elements.jsx'
import PageTwo from './page-two.jsx'

const Tabs = () => {
  const [activeTab, setActiveTab] = useState('tabs')
  return (
    <div>
        <div>
            <button onClick={() => setActiveTab('page-one')}>Page One</button>
            <button onClick={() => setActiveTab('page-two')}>Page Two</button>
        </div>
        {activeTab === 'page-one' && <PageOne />}
        {activeTab === 'page-two' && <PageTwo />}
    </div>
  )
}

export default Tabs
